let resuming=false;
async function resume(offline=true){if(resuming)return;resuming=true;try{while(session.busy)await new Promise(r=>setTimeout(r,10));await session.queue;if(!offline)await session.checkpoint();await session.catchUp({offline})}finally{audio.resetObservation();resuming=false;lastFrame=0}}
document.addEventListener('visibilitychange',()=>{gesture=null;pointers.clear();lastFrame=0;if(document.hidden){session.checkpoint()}else if(session.state)resume(true)});window.addEventListener('pagehide',()=>session.checkpoint());window.addEventListener('pageshow',e=>{resize();if(e.persisted&&session.state)resume(true)});
function frame(t){requestAnimationFrame(frame);renderer.draw(session.state,t);if(session.phase!=='ready'||session.busy||resuming||document.hidden){audio.resetObservation();lastFrame=0;return}const gap=Math.max(0,(Date.now()-session.stateWallAt)/1000);if(gap>.35){resume(false);return}const events=session.tick(gap);if(sound)audio.observe(session.state);if(events.length){renderer.notice(events,session.state);for(const e of events)if(['death','capture','fusion','map','formUnlock'].includes(e.type))logs.push(e.type==='formUnlock'?'收藏圖鑑：'+(formDefinition(e.formId)?.name_zh||e.formId):e.type==='death'?'你倒下了，等待城鎮復活。':e.type==='capture'?'獲得新的同行夥伴。':e.type==='fusion'?'融合結果已產生。':'抵達 '+MAPS[e.mapId].name_zh);logs=logs.slice(-3);$('#messageLog').textContent=logs.join('\n');}if(pendingInteraction&&!session.state.player.path.length){finishInteraction().catch(e=>toast(e.message))}if(t-lastUI>150){updateHUD();lastUI=t}if(t-lastSave>2000){lastSave=t;session.checkpoint()}lastFrame=t}
requestAnimationFrame(frame);
Promise.all([renderer.load(),session.start()]).catch(e=>session.block(e));
setInterval(()=>{if(!document.hidden&&session.phase==='readonly')session.retryOwnership().catch(e=>session.block(e))},2000);
if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'read_adventure_status',title:'讀取冒險狀態',description:'Read current local character and integration state without changing gameplay.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){const s=session.state;return s?{version:s.version,phase:session.phase,name:s.player.name,map:s.player.map,level:s.player.level,hp:s.player.hp,mp:s.player.mp,auto:s.auto,missingArt:[...renderer.missing]}:{phase:session.phase}}})).catch(()=>{})}catch{}

document.addEventListener('click',()=>{if(sound)audio.play('ASSET-AUDIO-UI::click')});
